      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <rect x="4" y="6" width="16" height="14" rx="1" /><path d="M4 10.5 L20 10.5 M8 3.5 L8 7 M16 3.5 L16 7" /><rect x="10" y="13" width="4" height="4" rx="0.6" />
